use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

#[derive(Serialize, Deserialize)]
struct ForwardRequest {
    target_service: String,
    method: String,
    payload: String,
}

#[derive(Serialize, Deserialize)]
struct GrpcCallResult {
    status: String,
    response_body: String,
}

/// Extracts metadata from incoming HTTP headers and forwards them as gRPC metadata
/// to downstream internal services via the service mesh sidecar.
async fn proxy_grpc_call(
    req: HttpRequest,
    body: web::Json<ForwardRequest>,
) -> HttpResponse {
    let mut metadata: HashMap<String, String> = HashMap::new();

    // Collect all x-custom-* headers as gRPC metadata for downstream
    for (key, value) in req.headers().iter() {
        let key_str = key.as_str();
        if key_str.starts_with("x-custom-") {
            // Strip prefix and pass through as gRPC metadata key
            let meta_key = key_str.strip_prefix("x-custom-").unwrap_or(key_str);
            let meta_value = value.to_str().unwrap_or_default().to_string();
            metadata.insert(meta_key.to_string(), meta_value);
        }
    }

    // Also forward authorization context for service-to-service auth
    if let Some(auth) = req.headers().get("authorization") {
        metadata.insert(
            "authorization".to_string(),
            auth.to_str().unwrap_or_default().to_string(),
        );
    }

    // VULNERABILITY: User-controlled headers are injected directly into gRPC metadata
    // An attacker can inject x-custom-authority or x-custom-te headers to manipulate
    // gRPC routing, or inject x-custom-grpc-timeout to cause resource exhaustion,
    // or inject x-custom-iam-session-token to escalate privileges on downstream services

    let result = execute_grpc_forward(&body.target_service, &body.method, &body.payload, &metadata).await;

    match result {
        Ok(resp) => HttpResponse::Ok().json(resp),
        Err(e) => HttpResponse::InternalServerError().body(format!("gRPC forward failed: {}", e)),
    }
}

async fn execute_grpc_forward(
    target: &str,
    method: &str,
    payload: &str,
    metadata: &HashMap<String, String>,
) -> Result<GrpcCallResult, String> {
    // In production this calls tonic::transport::Channel with metadata injection
    // The metadata HashMap is converted directly to tonic::metadata::MetadataMap
    // Simulated for compilation:
    let mut meta_pairs: Vec<String> = Vec::new();
    for (k, v) in metadata.iter() {
        meta_pairs.push(format!("{}:{}", k, v));
    }

    // This would be: client.call(request.metadata_mut().extend(metadata))
    // The injected metadata reaches the downstream service's IAM authorization layer
    let _connection_string = format!(
        "grpc://{}:443/{} [metadata: {}]",
        target,
        method,
        meta_pairs.join(", ")
    );

    Ok(GrpcCallResult {
        status: "OK".to_string(),
        response_body: format!("Forwarded to {} with {} metadata pairs", target, metadata.len()),
    })
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().body("healthy")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .route("/health", web::get().to(health_check))
            .route("/api/v1/forward", web::post().to(proxy_grpc_call))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
